import jwt
import sqlite3
import hashlib
import time
import os
import pickle
import hmac
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['DB_PATH'] = os.environ.get('DB_PATH', '/var/app/keys.db')
app.config['CACHE_DIR'] = os.environ.get('CACHE_DIR', '/tmp/session_cache')
SERVER_HMAC_KEY = os.environ.get('SERVER_HMAC_KEY', '').encode()

if not SERVER_HMAC_KEY:
    raise RuntimeError("SERVER_HMAC_KEY must be set")


def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DB_PATH'])
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()


class KeyStore:
    """Manages RSA public keys for JWT verification.
    Keys are stored with a key_id (kid) for lookup."""

    @staticmethod
    def initialize_db(db):
        db.execute('''
            CREATE TABLE IF NOT EXISTS signing_keys (
                kid TEXT PRIMARY KEY,
                public_key TEXT NOT NULL,
                algorithm TEXT NOT NULL DEFAULT 'RS256',
                created_at REAL NOT NULL,
                revoked INTEGER NOT NULL DEFAULT 0
            )
        ''')
        db.commit()

    @staticmethod
    def fetch_key(db, kid):
        """Fetch a signing key by its ID.
        Only accepts string kid values for security."""
        if not isinstance(kid, str):
            return None

        # Validate kid format: alphanumeric, hyphens, underscores only
        if not all(c.isalnum() or c in '-_' for c in kid):
            return None

        if len(kid) > 128:
            return None

        row = db.execute(
            "SELECT public_key, algorithm FROM signing_keys WHERE kid = ? AND revoked = 0",
            (kid,)
        ).fetchone()

        if row:
            return {'public_key': row['public_key'], 'algorithm': row['algorithm']}
        return None


class SessionCache:
    """Server-side session cache using signed serialization.
    Only stores and retrieves data that the server itself produced.
    The pickle usage is safe here because:
    1. Data is only written by the server (store method)
    2. Data is MAC-verified before deserialization
    3. The MAC key is server-secret, so attackers cannot forge valid cache entries
    """

    def __init__(self, cache_dir, signing_key):
        self.cache_dir = cache_dir
        self.signing_key = signing_key
        os.makedirs(cache_dir, exist_ok=True)

    def _compute_mac(self, data_bytes):
        return hmac.new(self.signing_key, data_bytes, hashlib.sha256).digest()

    def store(self, session_id, session_data):
        """Store session data (server-generated only)."""
        if not isinstance(session_id, str) or not session_id.isalnum():
            return False
        safe_id = hashlib.sha256(session_id.encode()).hexdigest()
        data_bytes = pickle.dumps(session_data, protocol=pickle.HIGHEST_PROTOCOL)
        mac = self._compute_mac(data_bytes)
        filepath = os.path.join(self.cache_dir, safe_id)
        with open(filepath, 'wb') as f:
            f.write(mac + data_bytes)
        return True

    def retrieve(self, session_id):
        """Retrieve and verify session data."""
        if not isinstance(session_id, str) or not session_id.isalnum():
            return None
        safe_id = hashlib.sha256(session_id.encode()).hexdigest()
        filepath = os.path.join(self.cache_dir, safe_id)
        if not os.path.exists(filepath):
            return None
        with open(filepath, 'rb') as f:
            content = f.read()
        if len(content) < 32:
            return None
        stored_mac = content[:32]
        data_bytes = content[32:]
        expected_mac = self._compute_mac(data_bytes)
        if not hmac.compare_digest(stored_mac, expected_mac):
            return None
        return pickle.loads(data_bytes)


def verify_token(token):
    """Verify a JWT token using the key indicated by the 'kid' header.
    Implements multi-algorithm support with key lookup."""
    try:
        # Decode header without verification to get kid
        unverified_header = jwt.get_unverified_header(token)
    except jwt.exceptions.DecodeError:
        return None

    kid = unverified_header.get('kid')
    if kid is None:
        return None

    db = get_db()
    key_info = KeyStore.fetch_key(db, kid)

    if key_info is None:
        return None

    try:
        payload = jwt.decode(
            token,
            key_info['public_key'],
            algorithms=[key_info['algorithm']],
            options={"require": ["exp", "sub", "iat"]}
        )
        return payload
    except (jwt.ExpiredSignatureError, jwt.InvalidTokenError):
        return None


def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        auth_header = request.headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return jsonify({'error': 'Missing token'}), 401

        token = auth_header[7:]
        payload = verify_token(token)

        if payload is None:
            return jsonify({'error': 'Invalid token'}), 401

        g.user_id = payload['sub']
        g.token_payload = payload
        return f(*args, **kwargs)
    return decorated


@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    db = get_db()
    user = db.execute(
        "SELECT id, username, email, role FROM users WHERE id = ?",
        (g.user_id,)
    ).fetchone()
    if user is None:
        return jsonify({'error': 'User not found'}), 404
    return jsonify(dict(user))


@app.route('/api/documents', methods=['GET'])
@require_auth
def list_documents():
    db = get_db()
    docs = db.execute(
        "SELECT id, title, created_at FROM documents WHERE owner_id = ? ORDER BY created_at DESC",
        (g.user_id,)
    ).fetchall()
    return jsonify([dict(d) for d in docs])


@app.route('/api/documents/<doc_id>', methods=['GET'])
@require_auth
def get_document(doc_id):
    db = get_db()
    doc = db.execute(
        "SELECT * FROM documents WHERE id = ? AND owner_id = ?",
        (doc_id, g.user_id)
    ).fetchone()
    if doc is None:
        return jsonify({'error': 'Not found'}), 404
    return jsonify(dict(doc))


if __name__ == '__main__':
    with app.app_context():
        db = get_db()
        KeyStore.initialize_db(db)
    app.run(host='127.0.0.1', port=8080)
